INSERT OR IGNORE INTO `entries` (`type`, `id`, `title`, `summary`, `category`, `stage`, `tags`, `content`, `takeaway`, `sources`, `date`, `status`, `published_at`, `updated_at`) VALUES ('tutorial', '大麦票务', '大麦票务', '偶尔想去看一场演唱会，但往往很难抢到门票，也很影响计划。所以需要一定的技术，那就开始吧。', '演唱会门票', NULL, '["大麦票务","抢票脚本"]', '多福朋友也是很爱音乐的人，但往往抢不到，多福的号以前抢票很好，帮抢的多了就触发了限制，不得不尝试使用科技。
**下面就开始演示教程：**
在Github上的HaTickets写了一个方案（ [Mobile(U2) / Desktop(Tauri+Rust) 方案](https://github.com/currycan/HaTickets)）。
✅ 适合你：有一台安卓真机、能用命令行（会敲 adb / poetry）、想给自己或家人抢票。 ⛔ 不适合你：没有安卓真机（iOS / 纯 PC / Mac 无真机都跑不了）、完全没碰过命令行、或期待“装个 App 点一下就抢”。这是一套需要动手配置的自动化工具，不是开箱即用的成品软件。
从 [Android 官方](https://developer.android.com/tools/releases/platform-tools)页面下载 Windows 版 Platform-Tools，解压后把其中的 platform-tools 文件夹加入系统 PATH；按 [Poetry 官方](https://python-poetry.org/docs/#installation)安装说明安装 Poetry。重开 PowerShell，运行 adb devices 和 poetry --version。前者应显示一行以 device 结尾的手机记录。
上述内容虽然看起来非常专业，但是我们有上帝的大脑**Codex**，我们可以交给它，完成以下内容，并将其完善。
把Github项目链接交给Codex，下载项目，再提示Codex补充电脑环境，最后进行配置的本地编写。这个过程很容易，接下来就是等Codex跑完全程。等待抢票即可。
后续多福将继续完善这个项目，期待一下吧。', '', '[{"label":"方案来源","href":"https://github.com/currycan/HaTickets"},{"label":"工具","href":"https://chatgpt.com/"}]', '2026-10-12', 'published', '2026-10-12', '2026-10-12');
INSERT OR IGNORE INTO `entries` (`type`, `id`, `title`, `summary`, `category`, `stage`, `tags`, `content`, `takeaway`, `sources`, `date`, `status`, `published_at`, `updated_at`) VALUES ('tutorial', '零基础科学上网指南-机场原理-订阅机制与保姆级配置教程', '零基础科学上网指南：机场原理、订阅机制与保姆级配置教程', '在网络日常使用中，访问国际学术资源、跨境电商、GitHub、流媒体平台（如 YouTube 4K、Netflix）或使用 ChatGPT 等 AI 工具时，经常会遇到网络受限的情况。本文将拆解“机场”与“订阅”的工作原理，并以熊云为例，带你完成从注册到客户端配置的全流程。', 'VPN机场', NULL, '["熊云"]', '**什么是“机场”与“订阅”？**
初次接触代理工具时容易混淆客户端与节点的关系。整个网络连接链路由三部分组成：**[本地设备] ---> [客户端软件] ---> [订阅链接分发] ---> [机场海外节点] ---> [目标网站]**
机场（节点服务商）：部署在海外各地区（如香港、日本、新加坡、美国等）的高速中继服务器集群。客户端软件： 运行在手机或电脑上的网络路由工具（如 Clash、Shadowrocket、v2rayN 等），负责将流量按规则转发。
订阅链接（Subscription URL）：一串由服务商生成的专属加密网址。
客户端通过该链接一键拉取所有节点信息与分流规则，并在节点变动时自动更新，无需手动逐个添加 IP。
平台介绍与注册：**[熊云](https://xn--9kq856f.com/)**是一家提供多协议支持的节点服务平台，具备以下特性：多协议覆盖： 支持 Shadowsocks、Vmess、Trojan 等主流抗封锁协议。流媒体与 AI 解锁： 针对 YouTube、Netflix、Disney+ 以及 OpenAI (ChatGPT)、Claude 等服务进行专线解锁优化。智能分流规则： 内置国内白名单与国外直连策略，访问国内网站不耗费代理流量且不降速。
注册入口官方推荐注册通道：[4NRTDTdx](https://my2.xiongyun.xyz/#/register?code=4NRTDTdx)，建议使用常用邮箱完成注册并妥善保存账号密码。
全平台客户端推荐不同操作系统对应不同的主流客户端，请根据你的设备选择对应的工具：
操作系统推荐客户端说明
| 平台 | 特点 | 
| --- | --- | 
| Windows Clash Verge/v2rayN | 界面现代、支持内核切换、系统代理一键开启 | 
| macOS Clash Verge/Surge | 原生适配 Apple Silicon，内存占用低。 |
| iOS/iPad | 推荐使用Clash Mi，功能完善，规则分流成熟 |
| AndroidClash Meta for Android/v2rayNG | 开源稳定，支持分应用代理 |
相应下载推荐及使用教程：**[虎云文档](https://docs.huyun.org/#/)**', '', '[{"label":"官方入口","href":"https://huyun.top/"},{"label":"虎云文档","href":"https://docs.huyun.org/#/"},{"label":"熊云入口","href":"https://xn--9kq856f.com/"},{"label":"软件下载仓库","href":"https://dl.hu-yunpan.top/s/M4s9?path=%2F"}]', '2026-08-28', 'published', '2026-08-28', '2026-08-28');
INSERT OR IGNORE INTO `entries` (`type`, `id`, `title`, `summary`, `category`, `stage`, `tags`, `content`, `takeaway`, `sources`, `date`, `status`, `published_at`, `updated_at`) VALUES ('tutorial', 'source-table-workflow', '用一张来源表，核对一条重要信息', '把结论、原始来源、发布时间、证据和待核实项放在同一张表里，减少被二手内容带偏。', '信息判断', NULL, '["来源核对","表格","信息整理"]', '## 先建立五列

- 结论：这条信息具体声称了什么。
- 原始来源：优先放法规、公告、论文或产品官网。
- 时间：发布日期和信息适用时间要分开写。
- 证据：只摘录真正支持结论的数字或段落。
- 待核实：目前还缺什么，哪些只是推测。

## 再做两次检查

先问“来源有没有直接支持结论”，再问“即使事实成立，解释是否只有一种”。价格、政策、软件版本等会变化的信息，要在行动前重新打开原始页面。

## 推荐表格字段

主题｜结论｜原始来源｜发布日期｜适用范围｜关键证据｜相反证据｜最后核对时间｜下一步。', '', '[]', '2026-08-28', 'published', '2026-08-28', '2026-08-28');
INSERT OR IGNORE INTO `entries` (`type`, `id`, `title`, `summary`, `category`, `stage`, `tags`, `content`, `takeaway`, `sources`, `date`, `status`, `published_at`, `updated_at`) VALUES ('tutorial', 'content-collection-system', '把零散网页整理成可追溯的内容库', '不追求收藏数量，用“收集—判断—提炼—复用”四步把网页变成自己的知识。', '内容搜集', NULL, '["内容库","工作流","复用"]', '## 收集时只做最低限度标记

保存标题、链接、作者、日期和一句“为什么值得留”。没有复用目的的收藏，很快会变成新的信息负担。

## 每周集中处理

- 删除已经失效或重复的链接。
- 给真正有用的内容补上原始来源。
- 用自己的话写三句话：它说了什么、依据是什么、我会怎么用。
- 把能直接执行的部分变成模板、清单或教程。

## 输出比收藏重要

一条信息只有进入判断、写作或行动，才真正属于你。内容库的目标不是显得知道很多，而是下次遇到同类问题时更快做出可靠判断。', '', '[]', '2026-08-28', 'published', '2026-08-28', '2026-08-28');
INSERT OR IGNORE INTO `entries` (`type`, `id`, `title`, `summary`, `category`, `stage`, `tags`, `content`, `takeaway`, `sources`, `date`, `status`, `published_at`, `updated_at`) VALUES ('tutorial', 'cross-border-information-safety', '跨境信息访问前，先做合规与安全检查', '理解网络工具、隐私和账号风险，优先使用合法、可信并符合所在地与单位规则的访问方式。', '网络与隐私', NULL, '["跨境信息","隐私","账号安全"]', '## 先确认三件事

- 所在地法律法规、单位网络政策和目标服务条款是否允许。
- 工具由谁提供，是否能核实开发者、隐私政策和更新渠道。
- 你准备登录什么账号，泄露后会造成多大损失。

## 不要把“能连接”当成“安全”

不要安装来源不明的客户端、证书或浏览器扩展；不要复用重要密码；为邮箱和核心账号启用双重验证；工作资料和私人资料尽量分开。任何承诺永久免费、要求关闭安全软件或索取高权限的工具，都应提高警惕。

## 更稳妥的内容获取方式

优先使用目标网站的官方中文页面、公开邮件订阅、RSS、学术数据库、出版社与图书馆资源。需要跨境访问时，应选择所在地允许、服务主体清楚、隐私条款可核实的正规方案。本文只讲判断框架，不提供规避网络监管的操作步骤。', '', '[]', '2026-08-28', 'published', '2026-08-28', '2026-08-28');
INSERT OR IGNORE INTO `entries` (`type`, `id`, `title`, `summary`, `category`, `stage`, `tags`, `content`, `takeaway`, `sources`, `date`, `status`, `published_at`, `updated_at`) VALUES ('record', '2026-08-28-leaving-is-also-a-choice', '改变不了环境时，离开也是一种负责', '先核实制度与审批，保留证据，算清生存账；短期可以锻炼，长期必须守住健康、生活和选择权。改变不了环境时，有准备地离开也是成熟的决定。', 'career-growth', NULL, '["#星宇股份","#劳动权益","#工作与生活","#勇敢离开"]', '先纠正一个容易混淆的名称：近期引发讨论的是常州星宇车灯股份有限公司，也就是“星宇股份”，并非“星宇科技”。公开报道显示，公司与 107 名 2026 届毕业生解除劳动合同；常州市人社部门调查后指出，其协商方式简单生硬、沟通解释不够充分。公司随后致歉、暂停人力资源总监职务，并提出三个月求职过渡支持。至于每一份解除是否构成违法，仍要结合劳动合同、解除理由、程序与证据逐案判断，不能仅凭网络标题替代法律结论。\n\n这件事刺痛人的地方，不只是 107 个岗位，而是求职者在市场承压时承担了远高于企业的试错成本。企业可以调整经营，但不能把招聘、扩张或预测失误悄无声息地全部转嫁给刚进入社会的人。真正专业的经营，应当把决策成本、沟通责任和补救方案一起承担起来。\n\n我也在这个阶段选择离职。原因并不是一时情绪，而是长期严重加班；据我掌握的情况，公司未取得适用于我岗位的不定时工作制批准，也没有向我出示相应审批文件，却以不定时工作制要求工作。按照《劳动法》第三十九条和浙江现行规定，企业实行不定时工作制，需要向当地劳动保障行政部门书面申请并经批准后实施；审批也不等于可以无限延长工作时间，企业仍应保障休息休假。对我而言，当制度边界长期不清、生活持续被工作挤压，离开就是一次经过衡量的止损。\n\n短期高强度工作确实可能锻炼沟通、抗压和业务能力，但锻炼必须有期限、有回报，也要能恢复。如果一个岗位长期依靠透支睡眠、关系和健康维持，所谓成长很可能只是在训练自己忍受不合理。生存很重要，但生存不应只剩工资到账；身体、时间、尊严和继续选择的能力，也都是个人资产。\n\n对普通人而言，最现实的做法不是口号式对抗，而是先核实、再留证、再判断：要求查看特殊工时审批的单位、岗位、人员范围和有效期；保留劳动合同、制度通知、考勤、排班、工作消息和工资记录；把自己的最低生活成本、现金缓冲与转岗周期算清楚。遇到争议，可以向当地人社部门、劳动保障监察机构或专业律师咨询，具体权利仍以所在地规则和个案证据为准。\n\n孟母三迁不是逃避，而是承认环境会塑造人。一个人很难凭意志改变公司的权力结构、考核方式和管理文化，但可以决定自己是否继续把最稀缺的时间交给它。留下要有留下的条件，离开也要有离开的准备：更新履历、整理成果、补足现金流、维持行业联系，把经历转换成下一份工作的判断标准。\n\n工作不是人生的全部，权益也不是等到被侵害后才想起来的补偿。真正可持续的发展，是能力、收入、健康、关系和自由度能够一起增长。改变不了环境时，勇敢离开并不丢人；它是在告诉自己，短期困难值得面对，但长期生活必须由自己负责。', '先核实制度与审批，保留证据，算清生存账；短期可以锻炼，长期必须守住健康、生活和选择权。改变不了环境时，有准备地离开也是成熟的决定。', '[{"label":"澎湃新闻：星宇股份解除 107 名应届毕业生劳动合同事件","href":"https://www.thepaper.cn/newsDetail_forward_33959045"},{"label":"浙江省人社厅：特殊工时制度须申请并经批准后实施","href":"https://rlsbt.zj.gov.cn/art/2014/2/24/art_1229506775_307500.html"},{"label":"人社部：不定时工作制和综合计算工时工作制审批办法","href":"https://www.mohrss.gov.cn/xxgk2020/gzk/gz/202112/P020211229609908265429.pdf"}]', '2026-08-28', 'published', '2026-08-28', '2026-08-28');
INSERT OR IGNORE INTO `entries` (`type`, `id`, `title`, `summary`, `category`, `stage`, `tags`, `content`, `takeaway`, `sources`, `date`, `status`, `published_at`, `updated_at`) VALUES ('record', '2026-08-13-direct-sales-boundaries', '短期先活下来，长期才有意义：在压力中争取边界、效率与利益', '先保生存，再谈长期；用事实向上反馈，用优先级管理工作，用明确条件争取权益，用效率减少无效劳动，并始终保留选择下一站的能力。', 'career-growth', NULL, '["#直营模式","#向上管理","#效率与权益","#个人无限公司"]', '最近开了一个单子，也让我重新思考用户、企业和一线销售之间的关系。用户希望价格更合适、权益更多、服务更充分；企业则必须守住成本、规则和经营底线。两边都没有错，这本来就是商业关系里长期存在的拉力。\n\n直营模式减少了传统经销环节，却没有消除利益差异。用户面对的不再是层层渠道，而是直接面对品牌；品牌的规则、价格和边界，也通过一线 Fellow 直接抵达用户。于是很多原本属于商业机制的矛盾，最后都集中到了离用户最近的人身上。\n\n但只谈不内耗和长期主义还不够。一个人如果当下的收入、时间和身体已经无法维持，长期就只是一句漂亮话；公司也一样，裁员、降薪、增加工作量可能缓解短期压力，却不能把经营问题无限转嫁给留下来的人。短期生存必须先被正视，责任也必须和资源、权限及回报相匹配。\n\n第一步是算清自己的生存账，而不是只算情绪账：最低收入是多少，现有工作量需要多少时间，哪些任务直接产生结果，哪些只是重复消耗，身体和家庭最多还能承受多久。把这些写成事实，才能判断眼前是一次可度过的困难，还是长期不可持续的结构。\n\n第二步是学会向上管理。向上管理不是讨好领导，也不是把问题扔回去，而是用“事实—影响—选项—请求—时间”沟通：现在新增了什么工作，占用多少时间，会影响哪个目标；我可以优先做 A 或 B，请确认顺序，或者补充资源、调整期限。新增一项任务，就要同时明确哪一项延后、取消或由谁支持。没有优先级的全部都要，本质上等于没有管理。\n\n第三步是把效率提升用在减少无效劳动，而不是证明自己还能承受更多。能模板化的沟通就模板化，能批量处理的跟进就集中处理，把用户按意向、匹配度和下一步动作分层；用数据记录线索数量、有效沟通、试驾、转化和售后投入。效率节省出来的时间，应当用于高价值服务和恢复能力，而不能自动变成新的无限工作量。\n\n第四步是具体争取自己的利益。不要只说“压力太大”或“希望理解”，而要提出可回应的条件：目标提高，对应需要什么线索、预算、人员和权限；职责扩大，对应如何调整收入、考核权重或休息安排；资源不给，就请管理者确认目标取舍和风险。争取不一定每次成功，但不表达、不留记录，就很容易被当成默认接受。\n\n管理者也有自己的职责。好的管理不是把上面的焦虑、数字和压力原样压给下面，更不是自己过不好就让团队也不好过；而是解释目标、排序任务、争取资源、承担取舍，并把一线真实情况反馈回决策层。管理的价值，就是消化复杂度、修正失真的目标，而不是充当压力传送带。\n\n这也不是鼓励推卸责任。个人要为承诺、结果和专业能力负责，公司和管理者则要为资源配置、规则、公平及可持续性负责。只要求责任，不提供相应权利和回报，就不是成长；长期以恐惧、羞辱或不可完成的目标迫使人超额承担，也不能被包装成奋斗。遇到重要调整，要保留书面目标、工作记录和沟通结果；必要时通过正式反馈渠道、可信赖的同事和专业咨询确认自己的选择。\n\n第五步是保留离场能力。更新履历、积累案例、维持行业联系、学习可迁移技能、建立一定现金缓冲，不代表随时准备逃跑，而是让谈判不只剩下忍耐。真正的安全感不是相信环境永远善待自己，而是即使合作不再公平，自己仍有选择下一站的能力。\n\n回到用户服务，我的角色不应该是无条件替任何一方争取，也不是替任何一方辩护。我应该把信息说清楚，把能争取与不能承诺的边界讲明白，判断双方是否真正匹配，并在合适的节奏里推进决定。高质量用户也不只是消费能力高，而是需求相对清楚、愿意沟通、尊重边界，并看得见专业服务的价值。\n\n所以答案不是忍耐，也不是把压力继续传给更弱的人，而是先保生存，再讲效率；先摆事实，再提方案；接受合理责任，也争取匹配的资源、权利和回报；能合作时把关系做得更好，不能合作时保留离开的能力。标准不是摆高姿态，而是让合作双方都被认真对待。\n\n不放低姿态，也不抬高自己；把心态放平，把事情做好。一次成交只是结果，真正需要积累的是判断、信誉、筛选能力和长期服务的节奏。把自己当作一家公司来经营，每一次沟通都在塑造产品，每一次取舍都在建立品牌。个人无限公司，准备中。', '先保生存，再谈长期；用事实向上反馈，用优先级管理工作，用明确条件争取权益，用效率减少无效劳动，并始终保留选择下一站的能力。', '[]', '2026-08-13', 'published', '2026-08-13', '2026-08-13');
INSERT OR IGNORE INTO `entries` (`type`, `id`, `title`, `summary`, `category`, `stage`, `tags`, `content`, `takeaway`, `sources`, `date`, `status`, `published_at`, `updated_at`) VALUES ('record', '2026-07-29-content-collections', '内容不是越堆越多，而是要慢慢长成清晰的集合', '长期内容要有分类、有路径、有入口；不是让页面显得很多，而是让用户更快找到对自己有用的那一篇。', 'career-growth', NULL, '["#网站整理","#内容集合","#长期积累"]', '今天重新看这个独立站，我意识到随心记录不能只是往下堆。前两篇记录一多，页面就会变长；以后如果持续更新几十篇、上百篇，访客反而更难找到真正需要的内容。\n\n所以网站需要从“流水账”变成“内容集合”：按日期能回看当天记录，按话题能看同一类经验，按教程能直接进入当前最相关的问题。这样首页保持简洁，但内容不会被折叠到没人看见。\n\n读者不需要我把所有信息一次性倒给他，而是需要在合适的时刻看到合适的内容。好的整理，本质上是在降低对方理解和行动的成本。', '长期内容要有分类、有路径、有入口；不是让页面显得很多，而是让用户更快找到对自己有用的那一篇。', '[]', '2026-07-29', 'published', '2026-07-29', '2026-07-29');
INSERT INTO `changelog` (`date`, `title`, `detail`) SELECT '2026-08-28', '建立教程内容库与本地发布工具', '生活效率新增教程、来源与更新日志结构；后续可以在本地编辑器中维护并发布。' WHERE NOT EXISTS (SELECT 1 FROM `changelog` WHERE `title` = '建立教程内容库与本地发布工具' AND `date` = '2026-08-28');
INSERT INTO `changelog` (`date`, `title`, `detail`) SELECT '2026-08-28', '发布教程：零基础科学上网指南：机场原理、订阅机制与保姆级配置教程', '在网络日常使用中，访问国际学术资源、跨境电商、GitHub、流媒体平台（如 YouTube 4K、Netflix）或使用 ChatGPT 等 AI 工具时，经常会遇到网络受限的情况。本文将拆解“机场”与“订阅”的工作原理，并以熊云为例，带你完成从注册到客户端配置的全流程。' WHERE NOT EXISTS (SELECT 1 FROM `changelog` WHERE `title` = '发布教程：零基础科学上网指南：机场原理、订阅机制与保姆级配置教程' AND `date` = '2026-08-28');
INSERT INTO `changelog` (`date`, `title`, `detail`) SELECT '2026-10-12', '发布教程：大麦票务', '偶尔想去看一场演唱会，但往往很难抢到门票，也很影响计划。所以需要一定的技术，那就开始吧。' WHERE NOT EXISTS (SELECT 1 FROM `changelog` WHERE `title` = '发布教程：大麦票务' AND `date` = '2026-10-12');
